const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Artículos</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>El artículo alemán no siempre coincide con el género de la palabra en español. Por eso, lo mejor es aprender los sustantivos junto con su artículo.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Ejemplos de artículos</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — mesa</div>\n      <div class=\"kurss-example\">die Tür — puerta</div>\n      <div class=\"kurss-example\">das Messer — cuchillo</div>\n      <div class=\"kurss-example\">das Mädchen — chica</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>A menudo DER</h4>\n    <p class=\"artikuli-explain\">DER suele usarse con personas de sexo masculino, días, meses, estaciones del año y algunas palabras con determinadas terminaciones.</p>\n\n    <h5 class=\"artikuli-subtitle\">Reglas</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → a menudo DER, por ejemplo: der Computer, der Lehrer <span class=\"artikuli-note\">pero no siempre</span></div>\n      <div class=\"kurss-example\">-ling → a menudo DER, por ejemplo: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → a menudo DER, por ejemplo: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">personas de sexo masculino → der Mann, der Vater</div>\n      <div class=\"kurss-example\">profesiones → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">marcas de coches → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">días → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">meses → der August, der Dezember</div>\n      <div class=\"kurss-example\">estaciones del año → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Ejemplos</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — hombre</div>\n      <div class=\"kurss-example\">der Vater — padre</div>\n      <div class=\"kurss-example\">der Montag — lunes</div>\n      <div class=\"kurss-example\">der August — agosto</div>\n      <div class=\"kurss-example\">der Sommer — verano</div>\n      <div class=\"kurss-example\">der Lehrer — profesor</div>\n      <div class=\"kurss-example\">der Computer — ordenador</div>\n      <div class=\"kurss-example\">der Schmetterling — mariposa</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>A menudo DIE</h4>\n    <p class=\"artikuli-explain\">DIE suele usarse con personas de sexo femenino, el plural y palabras con las terminaciones -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Reglas</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">personas de sexo femenino → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">marcas de motos → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">plural → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">el plural casi siempre → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Ejemplos</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — mujer</div>\n      <div class=\"kurss-example\">die Mutter — madre</div>\n      <div class=\"kurss-example\">die Wohnung — piso</div>\n      <div class=\"kurss-example\">die Rechnung — factura</div>\n      <div class=\"kurss-example\">die Freiheit — libertad</div>\n      <div class=\"kurss-example\">die Möglichkeit — posibilidad</div>\n      <div class=\"kurss-example\">die Mannschaft — equipo</div>\n      <div class=\"kurss-example\">die Nation — nación</div>\n      <div class=\"kurss-example\">die Universität — universidad</div>\n      <div class=\"kurss-example\">die Polizei — policía</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>A menudo DAS</h4>\n    <p class=\"artikuli-explain\">DAS suele usarse con los diminutivos en -chen / -lein, muchas palabras en -ment / -um y los verbos usados como sustantivos.</p>\n\n    <h5 class=\"artikuli-subtitle\">Reglas</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">metales → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">elementos químicos → das Eisen, das Kupfer</div>\n      <div class=\"kurss-example\">hoteles → das Hotel</div>\n      <div class=\"kurss-example\">colores como sustantivos → das Rot, das Blau</div>\n      <div class=\"kurss-example\">verbo como sustantivo → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">verbos como sustantivos → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Ejemplos</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — niño</div>\n      <div class=\"kurss-example\">das Mädchen — chica</div>\n      <div class=\"kurss-example\">das Häuschen — casita</div>\n      <div class=\"kurss-example\">das Instrument — instrumento</div>\n      <div class=\"kurss-example\">das Zentrum — centro</div>\n      <div class=\"kurss-example\">das Museum — museo</div>\n      <div class=\"kurss-example\">das Essen — comer / comida</div>\n      <div class=\"kurss-example\">das Lernen — aprendizaje</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Excepciones importantes / hay que aprenderlas con el artículo</h4>\n    <p class=\"artikuli-explain\">En algunas palabras, el artículo no se puede deducir con seguridad por la terminación ni por el género en español. Lo mejor es aprenderlas junto con su artículo.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — puerta</div>\n      <div class=\"kurss-example\">das Messer — cuchillo</div>\n      <div class=\"kurss-example\">die Sonne — sol</div>\n      <div class=\"kurss-example\">der Mond — luna</div>\n      <div class=\"kurss-example\">das Mädchen — chica</div>\n      <div class=\"kurss-example\">das Auto — coche</div>\n      <div class=\"kurss-example\">der Käse — queso</div>\n      <div class=\"kurss-example\">die Gabel — tenedor</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Las terminaciones y los grupos de palabras ayudan a adivinar el artículo, pero no son una regla 100% segura. Si no estás seguro, aprende la palabra junto con su artículo.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Pronombres</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ y Dativ — formas de los pronombres.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — ¿quién?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — yo</div><div class=\"kurss-example\">du — tú</div><div class=\"kurss-example\">er — él</div><div class=\"kurss-example\">sie — ella</div><div class=\"kurss-example\">es — ello (neutro)</div><div class=\"kurss-example\">wir — nosotros / nosotras</div><div class=\"kurss-example\">ihr — vosotros / vosotras</div><div class=\"kurss-example\">sie — ellos / ellas</div><div class=\"kurss-example\">Sie — usted / ustedes (formal)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — ¿qué?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — me</div><div class=\"kurss-example\">dich — te</div><div class=\"kurss-example\">ihn — lo (m.)</div><div class=\"kurss-example\">sie — la (f.)</div><div class=\"kurss-example\">es — lo</div><div class=\"kurss-example\">uns — nos</div><div class=\"kurss-example\">euch — os</div><div class=\"kurss-example\">sie — los / las</div><div class=\"kurss-example\">Sie — lo / la (formal)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — ¿a quién?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — me (a mí)</div><div class=\"kurss-example\">dir — te (a ti)</div><div class=\"kurss-example\">ihm — le (a él / a ello)</div><div class=\"kurss-example\">ihr — le (a ella)</div><div class=\"kurss-example\">uns — nos (a nosotros)</div><div class=\"kurss-example\">euch — os (a vosotros)</div><div class=\"kurss-example\">ihnen — les (a ellos / a ellas)</div><div class=\"kurss-example\">Ihnen — le / les (formal)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>¿Cómo elegir la forma?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — sujeto de la oración (¿quién realiza la acción?)</li><li><span class=\"case-red\">Akkusativ</span> — complemento directo (¿qué?)</li><li><span class=\"case-green\">Dativ</span> — complemento indirecto (¿a quién?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Ejemplos</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Te veo.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Lo veo.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Nos caéis bien.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Te ayudo.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Le doy un libro.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Os damos las gracias.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>El Nominativ es siempre el sujeto de la oración, mientras que el Akkusativ y el Dativ son complementos. Fíjate en el verbo y pregunta: <span class=\"case-red\">¿qué?</span> o <span class=\"case-green\">¿a quién?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Vocales: largas y cortas</h3>\n            <p class=\"kurss-lesson-intro\">En alemán, las vocales pueden ser largas o cortas. Esto influye en la pronunciación de la palabra.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Vocal larga</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">warm (varm) — cálido</div><div class=\"kurss-example\">gut (gūt) — bueno</div><div class=\"kurss-example\">Tat (tāt) — acción / hecho</div><div class=\"kurss-example\">Flur (flūr) — pasillo</div><div class=\"kurss-example\">Weg (vēk) — camino</div><div class=\"kurss-example\">Hut (jūt) — sombrero</div><div class=\"kurss-example\">Hof (jōf) — patio</div><div class=\"kurss-example\">Schlaf (shlāf) — sueño</div></div>\n              <p>Si a la vocal le sigue una sola consonante, la vocal suele pronunciarse larga.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Vocal corta</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Pilz (pilts) — seta / hongo</div><div class=\"kurss-example\">Wort (vort) — palabra</div><div class=\"kurss-example\">Mund (munt) — boca</div><div class=\"kurss-example\">bald (balt) — pronto</div><div class=\"kurss-example\">scharf (sharf) — afilado</div><div class=\"kurss-example\">Feld (felt) — campo</div><div class=\"kurss-example\">voll (fol) — lleno</div></div>\n              <p>Si a la vocal le siguen dos o más consonantes, la vocal suele pronunciarse corta.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Terminaciones en / el / er</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">singen (singuen) — cantar</div><div class=\"kurss-example\">tragen (trāguen) — llevar</div><div class=\"kurss-example\">Garten (garten) — jardín</div><div class=\"kurss-example\">Vogel (foguel) — pájaro</div><div class=\"kurss-example\">Segel (sēguel) — vela</div><div class=\"kurss-example\">Braten (brāten) — asado</div><div class=\"kurss-example\">Bogen (bōguen) — arco</div><div class=\"kurss-example\">Spiegel (shpīguel) — espejo</div><div class=\"kurss-example\">Finger (finguer) — dedo</div><div class=\"kurss-example\">Halter (jalter) — soporte</div><div class=\"kurss-example\">Arbeiter (arbaiter) — trabajador</div><div class=\"kurss-example\">Häuser (joiser) — casas</div><div class=\"kurss-example\">wieder (vīder) — de nuevo</div><div class=\"kurss-example\">breiter (braiter) — más ancho</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>La letra h como marca de vocal larga</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rahmen (rāmen) — marco</div><div class=\"kurss-example\">Ohr (ōr) — oreja</div><div class=\"kurss-example\">Kohle (kōle) — carbón</div><div class=\"kurss-example\">Zahl (tsāl) — número</div><div class=\"kurss-example\">ihn (īn) — lo (a él)</div><div class=\"kurss-example\">ihm (īm) — le (a él)</div><div class=\"kurss-example\">Huhn (jūn) — gallina</div><div class=\"kurss-example\">nahm (nām) — tomó</div><div class=\"kurss-example\">nehmen (nēmen) — tomar</div><div class=\"kurss-example\">Schuh (shū) — zapato</div></div>\n              <p>En algunas palabras, la h alarga la vocal anterior. En estos casos, la h normalmente no se pronuncia.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Terminaciones en e</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Lampe (lampe) — lámpara</div><div class=\"kurss-example\">Hase (jāse) — liebre</div><div class=\"kurss-example\">Knabe (knābe) — muchacho</div><div class=\"kurss-example\">Rabe (rābe) — cuervo</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>La i larga = ie</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">die (dī) — artículo «die»</div><div class=\"kurss-example\">diese (dīse) — esta / estos</div><div class=\"kurss-example\">wieder (vīder) — de nuevo</div><div class=\"kurss-example\">Fliege (flīgue) — mosca</div><div class=\"kurss-example\">Ziege (tsīgue) — cabra</div><div class=\"kurss-example\">Stiel (shtīl) — tallo / mango</div><div class=\"kurss-example\">Dieb (dīp) — ladrón</div><div class=\"kurss-example\">hier (jīr) — aquí</div></div>\n              <p>En alemán, la i larga se escribe a menudo como ie.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Vocales dobles</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Saal (sāl) — sala</div><div class=\"kurss-example\">Saat (sāt) — siembra / semilla</div><div class=\"kurss-example\">Staat (shtāt) — Estado</div><div class=\"kurss-example\">Beere (bēre) — baya</div><div class=\"kurss-example\">See (sē) — lago / mar</div><div class=\"kurss-example\">Beet (bēt) — bancal / arriate</div><div class=\"kurss-example\">Boot (bōt) — barca</div><div class=\"kurss-example\">Moor (mōr) — pantano / turbera</div><div class=\"kurss-example\">Moos (mōs) — musgo</div></div>\n              <p>Las vocales dobles se pronuncian normalmente largas.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ä</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Wand (vant) — pared</div><div class=\"kurss-example\">Wände (vende) — paredes</div><div class=\"kurss-example\">Vater (fāter) — padre</div><div class=\"kurss-example\">Väter (fēter) — padres</div><div class=\"kurss-example\">Schrank (shrank) — armario</div><div class=\"kurss-example\">Schränke (shrenke) — armarios</div><div class=\"kurss-example\">Bank (bank) — banco</div><div class=\"kurss-example\">Bänke (benke) — bancos (asientos)</div><div class=\"kurss-example\">Tal (tāl) — valle</div><div class=\"kurss-example\">Täler (tēler) — valles</div></div>\n              <p>La ä es la metafonía (Umlaut) de la a.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ö</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rose (rōse) — rosa</div><div class=\"kurss-example\">Röschen (rēsjen) — rosita</div><div class=\"kurss-example\">Ofen (ōfen) — horno / estufa</div><div class=\"kurss-example\">Öfen (ēfen) — hornos / estufas</div><div class=\"kurss-example\">Rock (rok) — falda</div><div class=\"kurss-example\">Röcke (röke) — faldas</div></div>\n              <p>La ö es la metafonía (Umlaut) de la o.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ü</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kurz (kurts) — corto</div><div class=\"kurss-example\">kürzer (kürtser) — más corto</div><div class=\"kurss-example\">Kunst (kunst) — arte</div><div class=\"kurss-example\">Künste (künste) — artes</div><div class=\"kurss-example\">Mutter (muter) — madre</div><div class=\"kurss-example\">Mütter (müter) — madres</div></div>\n              <p>La ü es la metafonía (Umlaut) de la u.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Diptongos: äu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Baum (baum) — árbol</div><div class=\"kurss-example\">Bäume (boime) — árboles</div><div class=\"kurss-example\">Haus (jaus) — casa</div><div class=\"kurss-example\">Häuser (joiser) — casas</div><div class=\"kurss-example\">Strauch (shtrauj) — arbusto</div><div class=\"kurss-example\">Sträucher (shtroijer) — arbustos</div><div class=\"kurss-example\">Maus (maus) — ratón</div><div class=\"kurss-example\">Mäuse (moise) — ratones</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Diptongos: eu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">heute (joite) — hoy</div><div class=\"kurss-example\">Leute (loite) — gente</div><div class=\"kurss-example\">neu (noi) — nuevo</div><div class=\"kurss-example\">neun (noin) — nueve</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Diptongos: ei</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">mein (main) — mi</div><div class=\"kurss-example\">dein (dain) — tu</div><div class=\"kurss-example\">sein (sain) — su (de él) / ser</div><div class=\"kurss-example\">frei (frai) — libre</div><div class=\"kurss-example\">arbeiten (arbaiten) — trabajar</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Notas de pronunciación de la clase 2</h4>\n              <ul class=\"kurss-summary-list\"><li>en las palabras ich, nicht, rechnen, zeichnen, la «ch» se pronuncia suave (como una «j» suave, casi una «y» soplada)</li><li>en las palabras arbeiten y zeichnen, la «ei» se pronuncia como «ai»</li><li>la «sp» al principio de palabra se pronuncia como «shp»</li><li>en el verbo tun, la «u» se pronuncia larga</li></ul>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Resumen</h4>\n              <ul class=\"kurss-summary-list\"><li>una consonante tras la vocal → a menudo vocal larga</li><li>dos o más consonantes → a menudo vocal corta</li><li>la h puede alargar la vocal</li><li>ie suele indicar una i larga</li><li>las vocales dobles suelen ser largas</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Consonantes y combinaciones de letras</h3>\n            <p class=\"kurss-lesson-intro\">En alemán, algunas consonantes y combinaciones de letras se pronuncian de forma distinta a como se escriben. En esta lección están los ejemplos más importantes para principiantes.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Consonantes</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">das Rad (rāt) — rueda</div><div class=\"kurss-example\">die Räder (rēder) — ruedas</div><div class=\"kurss-example\">Bad (bāt) — baño / bañera</div><div class=\"kurss-example\">Bäder (bēder) — baños / bañeras</div></div>\n              <p>Al final de la palabra, las consonantes a menudo no se pronuncian tal como se escriben.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ch</h4>\n              <p>La «ch» puede pronunciarse suave o fuerte. En algunas palabras suena como una «j» suave (casi una «y» soplada), en otras como la «j» española.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">rechnen (rejnen) — calcular</div><div class=\"kurss-example\">zeichnen (tsaijnen) — dibujar</div><div class=\"kurss-example\">nicht (nijt) — no</div><div class=\"kurss-example\">schlecht (shlejt) — malo</div><div class=\"kurss-example\">mich (mij) — me / a mí</div><div class=\"kurss-example\">dich (dij) — te / a ti</div><div class=\"kurss-example\">Strauch (shtrauj) — arbusto</div><div class=\"kurss-example\">noch (noj) — todavía / aún</div><div class=\"kurss-example\">Nacht (najt) — noche</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sch</h4>\n              <p>En alemán, la «sch» se pronuncia como «sh» (el sonido de «¡sh!» para pedir silencio).</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Schule (shūle) — escuela</div><div class=\"kurss-example\">Schüler (shūler) — alumno</div><div class=\"kurss-example\">Schiff (shif) — barco</div><div class=\"kurss-example\">Schraube (shraube) — tornillo</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sp y st al principio de palabra</h4>\n              <p>Al principio de palabra o de sílaba, la «sp» suele pronunciarse como «shp» y la «st» como «sht».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen (shpīlen) — jugar</div><div class=\"kurss-example\">Sprung (shprung) — salto</div><div class=\"kurss-example\">stehen (shtēen) — estar de pie</div><div class=\"kurss-example\">Stall (shtal) — establo</div><div class=\"kurss-example\">Stand (shtant) — posición / puesto</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>qu</h4>\n              <p>En alemán, la «qu» se pronuncia normalmente como «kv».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Qual (kvāl) — tormento</div><div class=\"kurss-example\">Quartier (kvartīr) — alojamiento / barrio</div><div class=\"kurss-example\">quer (kvēr) — de través / transversal</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>s y z</h4>\n              <p>Al principio de palabra, la «s» suele sonar como una «s» sonora, zumbante (como la «z» inglesa de «zoo»). La letra «z» en alemán suena como «ts».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">sagen (sāguen) — decir</div><div class=\"kurss-example\">singen (singuen) — cantar</div><div class=\"kurss-example\">Rose (rōse) — rosa</div><div class=\"kurss-example\">Zahl (tsāl) — número</div><div class=\"kurss-example\">Zeit (tsait) — tiempo</div><div class=\"kurss-example\">Zink (tsink) — zinc</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>v</h4>\n              <p>En alemán, la «v» se pronuncia a menudo como «f». En palabras extranjeras suele sonar como una «v» labiodental (como en inglés o francés, distinta de la «b»).</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Vater (fāter) — padre</div><div class=\"kurss-example\">von (fon) — de</div><div class=\"kurss-example\">viel (fīl) — mucho</div><div class=\"kurss-example\">vier (fīr) — cuatro</div><div class=\"kurss-example\">Villa (vila) — villa / chalet</div><div class=\"kurss-example\">Klavier (klavīr) — piano</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>x e y</h4>\n              <p>La «x» se pronuncia como «ks». La «y» en algunas palabras se pronuncia como «ü» (una «i» dicha con los labios redondeados como para la «u»).</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Felix (fēliks) — Félix</div><div class=\"kurss-example\">Axt (akst) — hacha</div><div class=\"kurss-example\">Mystik (mūstik) — mística</div><div class=\"kurss-example\">Mythe (mūte) — mito</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ß</h4>\n              <p>En alemán, la «ß» se pronuncia como «s».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Fuß (fūs) — pie</div><div class=\"kurss-example\">Füße (fūse) — pies</div><div class=\"kurss-example\">Grüße (grūse) — saludos</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Resumen</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → sh</li><li>sp / st al principio → shp / sht</li><li>qu → kv</li><li>z → ts</li><li>v a menudo → f</li><li>x → ks</li><li>ß → s</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Fundamentos de los verbos</h3>\n            <p class=\"kurss-lesson-intro\">Verbos de la lección 1 y sus formas (conjugación).</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Verbos</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kommen — venir</div><div class=\"kurss-example\">gehen — ir</div><div class=\"kurss-example\">stehen — estar de pie</div><div class=\"kurss-example\">singen — cantar</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>kommen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich komme — yo vengo</div><div class=\"kurss-example\">du kommst — tú vienes</div><div class=\"kurss-example\">er kommt — él viene</div><div class=\"kurss-example\">sie kommt — ella viene</div><div class=\"kurss-example\">wir kommen — nosotros venimos</div><div class=\"kurss-example\">ihr kommt — vosotros venís</div><div class=\"kurss-example\">sie kommen — ellos / ellas vienen</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>gehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich gehe — yo voy</div><div class=\"kurss-example\">du gehst — tú vas</div><div class=\"kurss-example\">er geht — él va</div><div class=\"kurss-example\">sie geht — ella va</div><div class=\"kurss-example\">wir gehen — nosotros vamos</div><div class=\"kurss-example\">ihr geht — vosotros vais</div><div class=\"kurss-example\">sie gehen — ellos / ellas van</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>stehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich stehe — yo estoy de pie</div><div class=\"kurss-example\">du stehst — tú estás de pie</div><div class=\"kurss-example\">er steht — él está de pie</div><div class=\"kurss-example\">sie steht — ella está de pie</div><div class=\"kurss-example\">wir stehen — nosotros estamos de pie</div><div class=\"kurss-example\">ihr steht — vosotros estáis de pie</div><div class=\"kurss-example\">sie stehen — ellos / ellas están de pie</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>singen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich singe — yo canto</div><div class=\"kurss-example\">du singst — tú cantas</div><div class=\"kurss-example\">er singt — él canta</div><div class=\"kurss-example\">sie singt — ella canta</div><div class=\"kurss-example\">wir singen — nosotros cantamos</div><div class=\"kurss-example\">ihr singt — vosotros cantáis</div><div class=\"kurss-example\">sie singen — ellos / ellas cantan</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Verbos de la lección 2</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen — jugar</div><div class=\"kurss-example\">arbeiten — trabajar</div><div class=\"kurss-example\">fragen — preguntar</div><div class=\"kurss-example\">antworten — responder</div><div class=\"kurss-example\">rechnen — calcular</div><div class=\"kurss-example\">zeichnen — dibujar</div><div class=\"kurss-example\">tun — hacer</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>spielen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich spiele — yo juego</div><div class=\"kurss-example\">du spielst — tú juegas</div><div class=\"kurss-example\">er spielt — él juega</div><div class=\"kurss-example\">sie spielt — ella juega</div><div class=\"kurss-example\">wir spielen — nosotros jugamos</div><div class=\"kurss-example\">ihr spielt — vosotros jugáis</div><div class=\"kurss-example\">sie spielen — ellos / ellas juegan</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>arbeiten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich arbeite — yo trabajo</div><div class=\"kurss-example\">du arbeitest — tú trabajas</div><div class=\"kurss-example\">er arbeitet — él trabaja</div><div class=\"kurss-example\">sie arbeitet — ella trabaja</div><div class=\"kurss-example\">wir arbeiten — nosotros trabajamos</div><div class=\"kurss-example\">ihr arbeitet — vosotros trabajáis</div><div class=\"kurss-example\">sie arbeiten — ellos / ellas trabajan</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>fragen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich frage — yo pregunto</div><div class=\"kurss-example\">du fragst — tú preguntas</div><div class=\"kurss-example\">er fragt — él pregunta</div><div class=\"kurss-example\">sie fragt — ella pregunta</div><div class=\"kurss-example\">wir fragen — nosotros preguntamos</div><div class=\"kurss-example\">ihr fragt — vosotros preguntáis</div><div class=\"kurss-example\">sie fragen — ellos / ellas preguntan</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>antworten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich antworte — yo respondo</div><div class=\"kurss-example\">du antwortest — tú respondes</div><div class=\"kurss-example\">er antwortet — él responde</div><div class=\"kurss-example\">sie antwortet — ella responde</div><div class=\"kurss-example\">wir antworten — nosotros respondemos</div><div class=\"kurss-example\">ihr antwortet — vosotros respondéis</div><div class=\"kurss-example\">sie antworten — ellos / ellas responden</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>rechnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich rechne — yo calculo</div><div class=\"kurss-example\">du rechnest — tú calculas</div><div class=\"kurss-example\">er rechnet — él calcula</div><div class=\"kurss-example\">sie rechnet — ella calcula</div><div class=\"kurss-example\">wir rechnen — nosotros calculamos</div><div class=\"kurss-example\">ihr rechnet — vosotros calculáis</div><div class=\"kurss-example\">sie rechnen — ellos / ellas calculan</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>zeichnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich zeichne — yo dibujo</div><div class=\"kurss-example\">du zeichnest — tú dibujas</div><div class=\"kurss-example\">er zeichnet — él dibuja</div><div class=\"kurss-example\">sie zeichnet — ella dibuja</div><div class=\"kurss-example\">wir zeichnen — nosotros dibujamos</div><div class=\"kurss-example\">ihr zeichnet — vosotros dibujáis</div><div class=\"kurss-example\">sie zeichnen — ellos / ellas dibujan</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>tun</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich tue — yo hago</div><div class=\"kurss-example\">du tust — tú haces</div><div class=\"kurss-example\">er tut — él hace</div><div class=\"kurss-example\">sie tut — ella hace</div><div class=\"kurss-example\">wir tun — nosotros hacemos</div><div class=\"kurss-example\">ihr tut — vosotros hacéis</div><div class=\"kurss-example\">sie tun — ellos / ellas hacen</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Estructura de la oración</h3>\n            <p class=\"kurss-lesson-intro\">En las oraciones interrogativas en alemán, el verbo suele ir en primer lugar.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Ejemplos</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Du kommst. — Tú vienes.</div><div class=\"kurss-example\">Kommst du? — ¿Vienes tú?</div><div class=\"kurss-example\">Er singt. — Él canta.</div><div class=\"kurss-example\">Singt er? — ¿Canta él?</div><div class=\"kurss-example\">Stehst du? — ¿Estás tú de pie?</div><div class=\"kurss-example\">Ja, ich stehe. — Sí, estoy de pie.</div><div class=\"kurss-example\">Geht ihr? — ¿Vais vosotros?</div><div class=\"kurss-example\">Ja, wir gehen. — Sí, vamos.</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Preguntas con «was»</h4>\n              <p>Si la pregunta empieza con una palabra interrogativa, el verbo en alemán suele ir inmediatamente después de la palabra interrogativa.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Was tust du? — ¿Qué haces tú?</div><div class=\"kurss-example\">Was tut er? — ¿Qué hace él?</div><div class=\"kurss-example\">Was tut sie? — ¿Qué hace ella?</div><div class=\"kurss-example\">Was tun sie? — ¿Qué hacen ellos / ellas?</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Negación con «nicht»</h4>\n              <p>Si la negación «nicht» se refiere al verbo, en alemán suele ir después del verbo.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich spiele nicht. — Yo no juego.</div><div class=\"kurss-example\">Paul fragt nicht. — Paul no pregunta.</div><div class=\"kurss-example\">Er kommt nicht. — Él no viene.</div><div class=\"kurss-example\">Sie singen nicht. — Ellos / ellas no cantan.</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Oraciones de la lección 2</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Spielst du? — ¿Juegas tú?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — No, no juego, trabajo.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Paul no pregunta, trabaja.</div><div class=\"kurss-example\">Arbeitest du? — ¿Trabajas tú?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — No, no trabajo, canto.</div><div class=\"kurss-example\">Was tut Paul? — ¿Qué hace Paul?</div><div class=\"kurss-example\">Er spielt. — Él juega.</div><div class=\"kurss-example\">Was tut Marie? — ¿Qué hace Marie?</div><div class=\"kurss-example\">Sie singt. — Ella canta.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Paul juega, pero Marie canta.</div><div class=\"kurss-example\">Singt ihr? — ¿Cantáis vosotros?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — No, no cantamos, trabajamos.</div><div class=\"kurss-example\">Was tun Paul und Marie? — ¿Qué hacen Paul y Marie?</div><div class=\"kurss-example\">Sie fragen. — Ellos preguntan.</div><div class=\"kurss-example\">Sie antworten nicht. — Ellos no contestan.</div><div class=\"kurss-example\">Wer arbeitet? — ¿Quién trabaja?</div><div class=\"kurss-example\">Wir arbeiten. — Nosotros trabajamos.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Nosotros calculamos y dibujamos.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Ellos / ellas vienen, preguntan, contestan, trabajan, juegan, cantan y se van.</div></div>\n            </section>",
  "kurssLesson2": "            <h3>Lección 2</h3>\n            <p class=\"kurss-lesson-intro\">Segunda lección: diálogos, vocabulario, pronunciación, gramática y traducción.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos / oraciones</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Vocabulario</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — jugar</div>\n                  <div class=\"kurss-example\">nein — no (respuesta)</div>\n                  <div class=\"kurss-example\">nicht — no (negación)</div>\n                  <div class=\"kurss-example\">arbeiten — trabajar</div>\n                  <div class=\"kurss-example\">fragen — preguntar</div>\n                  <div class=\"kurss-example\">was tut er? — ¿qué hace él?</div>\n                  <div class=\"kurss-example\">was tun sie? — ¿qué hacen ellos / ellas?</div>\n                  <div class=\"kurss-example\">aber — pero</div>\n                  <div class=\"kurss-example\">antworten — responder</div>\n                  <div class=\"kurss-example\">rechnen — calcular, hacer cuentas</div>\n                  <div class=\"kurss-example\">zeichnen — dibujar</div>\n                  <div class=\"kurss-example\">Marie — María</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciación</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">En las palabras ich, nicht, rechnen, zeichnen, el sonido ch se pronuncia suave, aproximadamente como una j muy suave articulada con la lengua pegada al paladar, casi como la y de «ya» pero sin voz.</div><div class=\"kurss-example\">En las palabras arbeiten, zeichnen, el diptongo ei se pronuncia aproximadamente como ai en «aire» o «baile».</div><div class=\"kurss-example\">El grupo consonántico sp se pronuncia shp: spielen (shpiilen).</div><div class=\"kurss-example\">En el verbo tun, la u se pronuncia larga en todas las personas.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Terminaciones con e</h4>\n                  <div class=\"lesson1-grammar-note\">Si la raíz del verbo termina en t, d o chn, en la conjugación se coloca una e delante de las terminaciones -st y -t.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>La palabra interrogativa</h4>\n                  <div class=\"lesson1-grammar-note\">En las oraciones interrogativas que empiezan con una palabra interrogativa, por ejemplo: ¿qué? ¿quién? ¿cuál? ¿por qué? ¿para qué?, etc., el verbo va inmediatamente después de la palabra interrogativa.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — ¿Qué haces?</div><div class=\"kurss-example\">Was tut er? — ¿Qué hace él?</div><div class=\"kurss-example\">Was tut sie? — ¿Qué hace ella?</div><div class=\"kurss-example\">Was tun sie? — ¿Qué hacen ellos / ellas?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>La negación con nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Si la negación nicht se refiere al verbo, la palabra negativa va detrás del verbo.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — Él no viene.</div><div class=\"kurss-example\">Sie singen nicht. — Ellos no cantan.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traduce</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Tarjeta de traducción de la Lección 2\">\n                    <span class=\"lesson1-training-progress\">Lección 2 · Traduce: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">¿Quién pregunta?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Haz clic en la tarjeta para ver la traducción al alemán. Después de la respuesta, el siguiente clic muestra la tarjeta siguiente.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson6": "\n    <h3>Lección 6</h3>\n    <p class=\"kurss-lesson-intro\">Los números, el plural, las vocales con umlaut y las formas del plural de los sustantivos.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos / oraciones</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Vocabulario</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — está, hay, está tumbado</div><div class=\"kurss-example\">der Bleistift (bláishtift) — el lápiz</div><div class=\"kurss-example\">einige (áinigue) — algunos, unos cuantos</div><div class=\"kurss-example\">hinlegen — dejar, poner</div><div class=\"kurss-example\">legt hin — deja, pone</div><div class=\"kurss-example\">wieder (víider) — otra vez, de nuevo</div><div class=\"kurss-example\">aufmachen — abrir</div><div class=\"kurss-example\">er macht auf — él abre</div><div class=\"kurss-example\">anspitzen (ánshpitsen) — sacar punta</div><div class=\"kurss-example\">er spitzt an — él saca punta</div><div class=\"kurss-example\">sich setzen — sentarse</div><div class=\"kurss-example\">setzt sich — se sienta</div><div class=\"kurss-example\">der Schlüssel (shlüsel) — la llave</div><div class=\"kurss-example\">das Fenster (fénster) — la ventana</div><div class=\"kurss-example\">die Tafel (dii táafel) — la pizarra</div><div class=\"kurss-example\">der Garten — el jardín</div><div class=\"kurss-example\">der Löffel — la cuchara</div><div class=\"kurss-example\">zählen (tséelen) — contar</div><div class=\"kurss-example\">die Nadel — la aguja</div><div class=\"kurss-example\">was ist das — ¿qué es esto?</div><div class=\"kurss-example\">der Hammer — el martillo</div><div class=\"kurss-example\">die Hämmer — los martillos</div><div class=\"kurss-example\">der Deckel (deer dékel) — la tapa</div><div class=\"kurss-example\">der Teller — el plato</div><div class=\"kurss-example\">der Wagen — el carro</div><div class=\"kurss-example\">der Schlitten — el trineo</div><div class=\"kurss-example\">das Ding — la cosa</div><div class=\"kurss-example\">die Dinge — las cosas</div><div class=\"kurss-example\">wie sind die Dinge? — ¿cómo son las cosas?</div><div class=\"kurss-example\">voll (fol) — lleno</div><div class=\"kurss-example\">leer (leer) — vacío</div><div class=\"kurss-example\">schwer (shveer) — pesado, difícil</div><div class=\"kurss-example\">leicht — ligero</div><div class=\"kurss-example\">der Eimer — el cubo</div><div class=\"kurss-example\">wieviel (víifiil) — cuánto, cuántos</div><div class=\"kurss-example\">wieviel Nadeln — cuántas agujas</div><div class=\"kurss-example\">hier (jiir) — aquí</div><div class=\"kurss-example\">dort — allí</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciación</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">La ä es la vocal a con umlaut y se pronuncia como una e cerrada, breve o larga.</div><div class=\"kurss-example\">Ejemplos: das Mädchen (méetjen), die Bänke (dii benke), der Vater (deer fáater), die Väter (dii féeter).</div><div class=\"kurss-example\">La ü es la vocal u con umlaut. Para pronunciarla, hay que redondear mucho los labios e intentar decir i con los labios redondeados.</div><div class=\"kurss-example\">Ejemplos: fünf, der Schlüssel (shlüsel).</div><div class=\"kurss-example\">La ö se pronuncia con los labios redondeados, intentando decir e: der Löffel.</div><div class=\"kurss-example\">Una vocal doble indica una vocal larga: leer (leer).</div><div class=\"kurss-example\">El diptongo eu se pronuncia oi: neun (noin).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Gramática y explicaciones</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">En presente, el prefijo tónico de un verbo compuesto se separa del verbo y va al final de la oración.</div><div class=\"kurss-example\">Ejemplos: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">El numeral uno tiene forma en los tres géneros cuando se usa con un sustantivo: en masculino ein, en femenino eine, en neutro ein.</div><div class=\"kurss-example\">Ejemplos: ein Schüler — un alumno; eine Schülerin — una alumna; ein Kind — un niño.</div><div class=\"kurss-example\">Números: eins, zwei, drei, vier (fiir), fünf, sechs (seks), sieben (siiben), acht, neun (noin), zehn (tseen).</div><div class=\"kurss-example\">En alemán, el verbo copulativo tiene forma de singular y de plural: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">En español, el demostrativo cambia en género y número, pero en alemán se usa una sola forma: das.</div><div class=\"kurss-example\">Ejemplos: este es un martillo — das ist ein Hammer; esta es una aguja — das ist eine Nadel; estos son martillos — das sind Hämmer; estas son agujas — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — carro y der Schlitten — trineo se usan en alemán tanto en singular como en plural.</div><div class=\"kurss-example\">Los sustantivos masculinos y neutros con la terminación -er, -el, -en a menudo no toman terminación en plural.</div><div class=\"kurss-example\">Ejemplos: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Los sustantivos femeninos con la terminación -el, -er toman -n en plural.</div><div class=\"kurss-example\">Ejemplos: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Excepciones: die Mutter (madre) — die Mütter (madres); die Tochter (hija) — die Töchter (hijas).</div><div class=\"kurss-example\">El artículo indeterminado no tiene plural: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">En la oración enunciativa, el verbo del predicado va en segundo lugar: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traduce</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Tarjeta de traducción de la Lección 6\"><span class=\"lesson1-training-progress\">Lección 6 · Traduce: 1 / 21</span><span class=\"lesson1-training-text\">Paul coge un lápiz y dibuja.</span></button><p class=\"lesson1-training-hint\">Haz clic en la tarjeta para ver la traducción al alemán. Después de la respuesta, el siguiente clic muestra la tarjeta siguiente.</p></div></div>\n    </details>\n  ",
  "kurssLesson5": "\n    <h3>Lección 5</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, el acusativo, sitzen, fragen y la terminación -in.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos / oraciones</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Vocabulario</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (sitsen) — estar sentado</div>\n        <div class=\"kurss-example\">fragen (fráaguen) — preguntar</div>\n        <div class=\"kurss-example\">der Lehrer (deer léerer) — el profesor</div>\n        <div class=\"kurss-example\">gut (guut) — bien</div>\n        <div class=\"kurss-example\">wen (veen) — a quién</div>\n        <div class=\"kurss-example\">loben — elogiar, alabar</div>\n        <div class=\"kurss-example\">der Schüler (shüler) — el alumno</div>\n        <div class=\"kurss-example\">klein — pequeño</div>\n        <div class=\"kurss-example\">groß (groos) — grande</div>\n        <div class=\"kurss-example\">die Lehrerin — la profesora</div>\n        <div class=\"kurss-example\">die Schülerin — la alumna</div>\n        <div class=\"kurss-example\">schlecht (shlejt) — mal</div>\n        <div class=\"kurss-example\">tadeln — reprender, regañar</div>\n        <div class=\"kurss-example\">oder (óoder) — o</div>\n        <div class=\"kurss-example\">das Kind (kint) — el niño</div>\n        <div class=\"kurss-example\">artig (áartij) — obediente, formal</div>\n        <div class=\"kurss-example\">die Mutter — la madre</div>\n        <div class=\"kurss-example\">lieben (liiben) — querer, amar</div>\n        <div class=\"kurss-example\">der Vater (fáater) — el padre</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciación</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz es una z doble y se pronuncia ts: sitzen (sitsen).</div>\n        <div class=\"kurss-example\">En las palabras alemanas, la v se pronuncia como f: der Vater (fáater).</div>\n        <div class=\"kurss-example\">La ß se llama eszett y se pronuncia como la s española: groß (groos), weiß (vais).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nominativo y acusativo</h4><div class=\"lesson1-grammar-note\">En español, el sujeto responde a la pregunta ¿quién? o ¿qué?, y el complemento directo a la pregunta ¿a quién? o ¿qué?.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">En alemán, la pregunta del nominativo es wer? para personas y was? para cosas.</div><div class=\"kurss-example\">En acusativo, la pregunta es wen? para personas y was? para cosas.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">El cambio del artículo en acusativo</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + acusativo</h4><div class=\"lesson1-grammar-note\">En alemán, el verbo fragen rige acusativo.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">La terminación -in</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Muchos sustantivos femeninos se forman con la terminación -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">La posición del verbo</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">En la oración enunciativa, el verbo va en segundo lugar.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traduce</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Tarjeta de traducción de la Lección 5\"><span class=\"lesson1-training-progress\">Lección 5 · Traduce: 1 / 16</span><span class=\"lesson1-training-text\">¿A quién quiere el padre?</span></button><p class=\"lesson1-training-hint\">Haz clic en la tarjeta para ver la traducción al alemán. Después de la respuesta, el siguiente clic muestra la tarjeta siguiente.</p></div></div>\n    </details>\n  ",
  "kurssLesson4": "            <h3>Lección 4</h3>\n            <p class=\"kurss-lesson-intro\">El acusativo, nehmen, hinlegen, hinausgehen y los adjetivos.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos / oraciones</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Vocabulario</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (neemen) — coger, tomar</div><div class=\"kurss-example\">er nimmt (nimt) — él coge</div><div class=\"kurss-example\">der Federhalter (deer féederjalter) — el portaplumas</div><div class=\"kurss-example\">einen Federhalter — un portaplumas</div><div class=\"kurss-example\">zeigen — mostrar, enseñar</div><div class=\"kurss-example\">schwarz (shvarts) — negro</div><div class=\"kurss-example\">weiß (vais) — blanco</div><div class=\"kurss-example\">die Feder (dii féeder) — la plumilla</div><div class=\"kurss-example\">eine Feder — una plumilla</div><div class=\"kurss-example\">spitz (shpits) — puntiagudo</div><div class=\"kurss-example\">hinlegen — dejar, poner</div><div class=\"kurss-example\">legt hin — deja, pone</div><div class=\"kurss-example\">das Mädchen (méetjen) — la niña</div><div class=\"kurss-example\">das Messer — el cuchillo</div><div class=\"kurss-example\">ein Messer — un cuchillo</div><div class=\"kurss-example\">scharf — afilado</div><div class=\"kurss-example\">stumpf (shtumpf) — desafilado, romo</div><div class=\"kurss-example\">dann — luego, entonces</div><div class=\"kurss-example\">hinaus — fuera</div><div class=\"kurss-example\">hinausgehen — salir</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciación</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Las terminaciones -en, -er, -el son átonas, por eso la e de estas terminaciones apenas se oye: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">En alemán, la h puede ser un sonido o una señal de que la vocal anterior es larga.</div><div class=\"kurss-example\">Si la h indica que la vocal es larga, no se pronuncia: nehmen (neemen).</div><div class=\"kurss-example\">Si a una vocal le sigue una sola consonante, la vocal se pronuncia larga: die (dii) Feder (féeder), den (deen).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>El acusativo</h4><div class=\"lesson1-grammar-note\">En femenino y neutro, el acusativo es igual al nominativo. Solo cambia el masculino.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Los pronombres</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — masculino</div><div class=\"kurss-example\">sie — femenino</div><div class=\"kurss-example\">es — neutro</div><div class=\"kurss-example\">en plural — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Verbos separables</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Los adjetivos</h4><div class=\"lesson1-grammar-note\">Si el adjetivo funciona como atributo en la oración, no varía ni en género ni en número.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>La negación con nicht</h4><div class=\"lesson1-grammar-note\">Si nicht niega un adjetivo, va delante de la palabra negada.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Los sustantivos con la terminación -chen y -lein son neutros: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traduce</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Tarjeta de traducción de la Lección 4\"><span class=\"lesson1-training-progress\">Lección 4 · Traduce: 1 / 16</span><span class=\"lesson1-training-text\">La niña coge un portaplumas.</span></button><p class=\"lesson1-training-hint\">Haz clic en la tarjeta para ver la traducción al alemán. Después de la respuesta, el siguiente clic muestra la tarjeta siguiente.</p></div></div></details>",
  "kurssLesson3": "            <h3>Lección 3</h3>\n            <p class=\"kurss-lesson-intro\">Tercera lección: diálogos, vocabulario, pronunciación, gramática y traducción.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos / oraciones</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Vocabulario</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — quién</div><div class=\"kurss-example\">was — qué</div><div class=\"kurss-example\">hier — aquí</div><div class=\"kurss-example\">dort — allí</div><div class=\"kurss-example\">der Tisch — la mesa</div><div class=\"kurss-example\">ein Tisch — una mesa</div><div class=\"kurss-example\">die Bank — el banco</div><div class=\"kurss-example\">eine Bank — un banco</div><div class=\"kurss-example\">liegen — estar tumbado (en posición horizontal)</div><div class=\"kurss-example\">liegt hier ein Buch? — ¿hay un libro aquí?</div><div class=\"kurss-example\">das Buch — el libro</div><div class=\"kurss-example\">ein Buch — un libro</div><div class=\"kurss-example\">hängen — colgar, estar colgado</div><div class=\"kurss-example\">das Bild — el cuadro</div><div class=\"kurss-example\">ein Bild — un cuadro</div><div class=\"kurss-example\">die Tafel — la pizarra</div><div class=\"kurss-example\">eine Tafel — una pizarra</div><div class=\"kurss-example\">wie — cómo</div><div class=\"kurss-example\">ist — es</div><div class=\"kurss-example\">dick — grueso, gordo</div><div class=\"kurss-example\">das Heft — el cuaderno</div><div class=\"kurss-example\">ein Heft — un cuaderno</div><div class=\"kurss-example\">dünn — delgado, fino</div><div class=\"kurss-example\">niedrig — bajo</div><div class=\"kurss-example\">hoch — alto</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciación</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">En alemán, el sonido i largo se escribe ie: liegen (liiguen), hier (jiir), wie (vii).</div><div class=\"kurss-example\">ck es una k doble: dick (dik).</div><div class=\"kurss-example\">En los adjetivos y adverbios, la terminación -ig suena como una -ich suave: niedrig (níidrij).</div><div class=\"kurss-example\">Si a la terminación -ig se le añade una e, es decir, -ige, la g se pronuncia como una g fuerte: niedrige (níidrigue) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>El sujeto</h4><div class=\"lesson1-grammar-note\">En alemán, el sujeto responde a la pregunta wer? / was? y va en nominativo.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Con wer? se pregunta por personas.</div><div class=\"kurss-example\">Con was? se pregunta por cosas.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Los artículos</h4><div class=\"lesson1-grammar-note\">En alemán, los sustantivos tienen 3 géneros: masculino, femenino y neutro. Delante del sustantivo suele ir una palabrita llamada artículo. Corresponde aproximadamente a los artículos españoles el, la, un, una.</div><h5 class=\"lesson2-subtitle\">El artículo determinado</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">masculino — der</div><div class=\"kurss-example\">femenino — die</div><div class=\"kurss-example\">neutro — das</div><div class=\"kurss-example\">En plural, el artículo determinado es die para los tres géneros.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">El artículo indeterminado</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">masculino — ein</div><div class=\"kurss-example\">femenino — eine</div><div class=\"kurss-example\">neutro — ein</div><div class=\"kurss-example\">El artículo indeterminado no tiene plural.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Los nombres propios</h4><div class=\"lesson1-grammar-note\">Delante de los nombres propios no se usa artículo.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>La posición del verbo</h4><div class=\"lesson1-grammar-note\">En la oración enunciativa, el verbo va en segundo lugar.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">En alemán, de los objetos que están en posición vertical se dice que están de pie:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">De los objetos que están en posición horizontal se dice que están tumbados:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Los objetos también pueden estar colgados:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traduce</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Tarjeta de traducción de la Lección 3\"><span class=\"lesson1-training-progress\">Lección 3 · Traduce: 1 / 22</span><span class=\"lesson1-training-text\">¿Haces cuentas?</span></button><p class=\"lesson1-training-hint\">Haz clic en la tarjeta para ver la traducción al alemán. Después de la respuesta, el siguiente clic muestra la tarjeta siguiente.</p></div></div></details>",
  "kurssLesson7": "            <h3>Lección 7</h3>\n            <p class=\"kurss-lesson-intro\">Séptima lección: el imperativo, la forma de cortesía y el plural.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos / oraciones</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Vocabulario</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — cantar</div><div class=\"kurss-example\">singe — canta</div><div class=\"kurss-example\">singt — cantad</div><div class=\"kurss-example\">singen Sie — cante usted, canten ustedes</div><div class=\"kurss-example\">das Lied (das liit) — la canción</div><div class=\"kurss-example\">Sie — usted, ustedes</div><div class=\"kurss-example\">zählen — contar</div><div class=\"kurss-example\">das Fräulein (fróilain) — la señorita</div><div class=\"kurss-example\">der Müller — el molinero</div><div class=\"kurss-example\">öffnen — abrir</div><div class=\"kurss-example\">das Fenster (fénster) — la ventana</div><div class=\"kurss-example\">alle — todos</div><div class=\"kurss-example\">der Spiegel (shpíiguel) — el espejo</div><div class=\"kurss-example\">der Lappen — el trapo, la bayeta</div><div class=\"kurss-example\">der Spaten — la pala</div><div class=\"kurss-example\">der Besen — la escoba</div><div class=\"kurss-example\">die Schaufel — la pala pequeña, el recogedor</div><div class=\"kurss-example\">die Schüssel — el cuenco, la fuente</div><div class=\"kurss-example\">das Zimmer — la habitación</div><div class=\"kurss-example\">das Ufer (úufer) — la orilla</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciación</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp al principio de una palabra o sílaba se pronuncia shp: der Spiegel (deer shpíiguel).</div><div class=\"kurss-example\">sch se pronuncia como la sh inglesa, el sonido que hacemos para pedir silencio: die Schaufel (dii sháufel), die Schüssel (dii shüsel).</div><div class=\"kurss-example\">El diptongo äu se pronuncia como oi en español: das Fräulein (das fróilain).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>El imperativo</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">El imperativo de la 2.ª persona del singular corresponde a la 2.ª persona del singular del verbo sin la terminación personal -st, añadiendo la terminación -e.</div><div class=\"kurss-example\">Ejemplos: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Muy a menudo no se usa la terminación -e si, sin ella, la forma del imperativo es monosílaba: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>El imperativo plural</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">El imperativo de la 2.ª persona del plural es igual a la 2.ª persona del plural del presente, pero se usa sin pronombre.</div><div class=\"kurss-example\">Ejemplos: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>La forma de cortesía con Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">La forma de cortesía, que en español corresponde a «usted», es igual a la 3.ª persona del plural. El pronombre Sie se escribe con mayúscula y va detrás del verbo.</div><div class=\"kurss-example\">Ejemplos: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Para facilitar la pronunciación, el verbo öffnen intercala una e entre la raíz y la terminación en la 2.ª y 3.ª persona del singular y en la 2.ª persona del plural: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Ejercicio</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Tarjeta de ejercicio de la Lección 7\"><span class=\"lesson1-training-progress\">Lección 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — preguntar</span></button><p class=\"lesson1-training-hint\">Toca la tarjeta para ver las formas del imperativo.</p></div></div></details>",
  "kurssLesson1": "            <h3>Lección 1</h3>\n            <p class=\"kurss-lesson-intro\">Primera lección: verbos en presente, vocabulario, pronunciación, gramática y traducción.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Verbos en presente</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Los verbos y su conjugación en presente.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — venir</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>yo vengo</span><span>du</span><strong>kommst</strong><span>tú vienes</span><span>er / sie</span><strong>kommt</strong><span>él / ella viene</span><span>wir</span><strong>kommen</strong><span>nosotros venimos</span><span>ihr</span><strong>kommt</strong><span>vosotros venís</span><span>sie / Sie</span><strong>kommen</strong><span>ellos / ustedes vienen</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — ir</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>yo voy</span><span>du</span><strong>gehst</strong><span>tú vas</span><span>er / sie</span><strong>geht</strong><span>él / ella va</span><span>wir</span><strong>gehen</strong><span>nosotros vamos</span><span>ihr</span><strong>geht</strong><span>vosotros vais</span><span>sie / Sie</span><strong>gehen</strong><span>ellos / ustedes van</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — estar de pie</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>yo estoy de pie</span><span>du</span><strong>stehst</strong><span>tú estás de pie</span><span>er / sie</span><strong>steht</strong><span>él / ella está de pie</span><span>wir</span><strong>stehen</strong><span>nosotros estamos de pie</span><span>ihr</span><strong>steht</strong><span>vosotros estáis de pie</span><span>sie / Sie</span><strong>stehen</strong><span>ellos / ustedes están de pie</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — cantar</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>yo canto</span><span>du</span><strong>singst</strong><span>tú cantas</span><span>er / sie</span><strong>singt</strong><span>él / ella canta</span><span>wir</span><strong>singen</strong><span>nosotros cantamos</span><span>ihr</span><strong>singt</strong><span>vosotros cantáis</span><span>sie / Sie</span><strong>singen</strong><span>ellos / ustedes cantan</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Ejemplos</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Vocabulario</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>La pronunciación aproximada de las palabras se indica entre paréntesis con la ortografía española.<br>Tenlo en cuenta también en las lecciones siguientes.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (viir) — nosotros</div><div class=\"kurss-example\">En la palabra «wir», la letra i se pronuncia larga.</div><div class=\"kurss-example\">kommen (kómen) — venir</div><div class=\"kurss-example\">gehen (guee-en) — ir</div><div class=\"kurss-example\">stehen (shtee-en) — estar de pie</div><div class=\"kurss-example\">singen (singuen) — cantar</div><div class=\"kurss-example\">du (duu) kommst — tú vienes</div><div class=\"kurss-example\">er (eer) kommt — él viene</div><div class=\"kurss-example\">sie (sii) kommt — ella viene</div><div class=\"kurss-example\">wer (veer) — ¿quién?</div><div class=\"kurss-example\">ja (yaa) — sí</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciación</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">La pronunciación correcta de las palabras, escrita con la ortografía española, se indica en las lecciones.</div><div class=\"kurss-example\">Wir (viir) — nosotros. En la palabra wir, la i se pronuncia siempre larga.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>El infinitivo</h4><div class=\"lesson1-grammar-note\">La forma básica del verbo. Normalmente el infinitivo termina en -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Terminaciones del presente</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Quita <span class=\"lesson1-ending-accent\">-en</span> del infinitivo y añade la terminación.</strong></p><p>Ejemplo: kommen → komm + terminación</p><div class=\"lesson1-ending-process\" aria-label=\"Cómo se forman las terminaciones del presente\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>forma básica</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>quita <span class=\"lesson1-ending-accent\">-en</span></strong><span>queda la raíz</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>raíz</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>añade la terminación</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Ejemplos</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Oraciones interrogativas</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>En las oraciones interrogativas alemanas, el verbo suele pasar al primer lugar.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">En español:<br>Tú vienes.<br>¿Vienes tú?</div><div class=\"kurss-example\">En alemán:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — tú vienes<br>kommst du? — ¿vienes tú?</div><div class=\"kurss-example\">er singt — él canta<br>singt er? — ¿canta él?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Diferencia de persona</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — él viene</div><div class=\"kurss-example\">sie kommt — ella viene</div><div class=\"kurss-example\">sie kommen — ellos / ellas vienen</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traduce</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Tarjeta de práctica de la Lección 1\">\n                    <span class=\"lesson1-training-progress\">Lección 1 · Traduce: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">¿Vienes?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Haz clic en la tarjeta para ver la traducción al alemán. Después de la respuesta, el siguiente clic muestra la tarjeta siguiente.</p>\n                </div>\n              </div>\n            </details>"
};

